baselineSql:
create table public.profiles (
  id uuid primary key,
  user_id uuid not null,
  email text not null,
  display_name text
);

create table public.todos (
  id uuid primary key,
  user_id uuid not null,
  title text not null,
  done boolean not null default false
);
alter table public.todos enable row level security;
create policy todos_owner on public.todos for all to authenticated using (auth.uid() = user_id) with check (auth.uid() = user_id);

releaseSql:
-- release adds a contact export and its job queue. No blanket grant line here; the UI toggle adds one.
create table public.exports (
  id uuid primary key,
  user_id uuid not null,
  email text not null,
  phone text not null
);

create table public.export_jobs (
  id uuid primary key,
  user_id uuid not null,
  status text not null
);
alter table public.export_jobs enable row level security;
